-- Workplace-only copy. Does not modify public.courses, Acuity, prices or qualifications.
-- Run after sql/01_workplace_courses.sql. Review claims and course availability before publishing.
WITH copy(slug, title, summary, description, ideal_for, delivery) AS (
 VALUES
 ('providecpr', 'CPR Training for Workplaces', 'Give your team the confidence to respond when every second counts. Practical CPR and AED training, organised around your workplace.', 'Help your people recognise a cardiac or breathing emergency and respond with practical CPR and defibrillator skills. This hands-on course is ideal for keeping designated first aiders and wider teams prepared. We can discuss a group session at your workplace or places in a suitable scheduled class at Truganina.', 'Workplace first aid officers, customer-facing teams, schools, hospitality, retail and any organisation looking to strengthen emergency readiness.', 'On-site group training across Victoria, or suitable scheduled sessions at our Truganina training centre.'),
 ('firstaidcpr', 'Workplace First Aid & CPR', 'Practical first aid and CPR skills for the injuries and medical emergencies that can happen at work.', 'Build a capable first aid response across your workplace. This course covers CPR, AED use, common injuries and sudden illness, helping nominated first aiders act with confidence while emergency services are on the way. We can help coordinate training for an entire team, individual new starters or multiple locations.', 'Designated workplace first aid officers, supervisors, operations teams and businesses reviewing their first aid arrangements.', 'Flexible on-site group sessions across Victoria; suitable scheduled sessions at Truganina for individual employees.'),
 ('educationandchildcare', 'First Aid for Education & Childcare Teams', 'First aid training tailored to the everyday realities of schools, early learning centres and care environments.', 'Prepare educators and carers to respond to first aid emergencies involving children and adults. This training covers CPR and the management of common injuries and medical emergencies relevant to education and care settings, including asthma and anaphylaxis. We can help plan training around staffing requirements and busy centre schedules.', 'Childcare educators, early learning services, outside-school-hours care teams and school staff.', 'On-site group training by arrangement; suitable scheduled sessions at Truganina.'),
 ('asthmaandanaphylaxis', 'Asthma & Anaphylaxis Response Training', 'Help your staff recognise and respond to asthma attacks and severe allergic reactions.', 'Make sure your team understands the warning signs of asthma and anaphylaxis and the importance of a prompt, appropriate emergency response. This practical training is especially relevant where staff care for children or support people with known allergies and asthma management plans. Course codes and current accreditation details should be confirmed with our team before enrolment.', 'Education and childcare teams, community organisations, sporting groups and workplaces supporting people at risk of asthma or anaphylaxis.', 'Ask us about group training at your premises and current available delivery options.'),
 ('advancedfirstaid', 'Advanced First Aid for Workplace Responders', 'Equip designated responders with broader skills for complex and high-pressure first aid incidents.', 'Designed for workplaces where nominated staff may need to manage more challenging incidents, this training builds on core first aid knowledge with advanced response, casualty assessment and coordination skills. Talk to us about your site risks and team responsibilities so we can help you choose an appropriate training approach.', 'Senior first aid officers, emergency response teams, high-risk workplaces and staff with additional response responsibilities.', 'Group training arrangements can be discussed for your workplace; availability and any pre-course requirements are confirmed before booking.'),
 ('manualhandling', 'Safe Manual Handling for Teams', 'Practical techniques to help staff identify hazardous manual tasks and reduce injury risks at work.', 'Support safer everyday work with training focused on recognising manual task hazards, planning movements and using safer handling techniques and equipment. We can discuss the tasks your employees actually perform, making it easier to connect training with your workplace procedures and environment.', 'Warehousing, logistics, healthcare, aged care, retail, hospitality and teams whose work involves lifting, carrying, pushing or repetitive movements.', 'On-site group training by arrangement, with delivery planned around your team and work environment.'),
 ('firewarden', 'Fire Warden Training for Workplaces', 'Help nominated wardens understand their roles and respond calmly during workplace emergencies.', 'Prepare your fire wardens to raise alarms, assist with evacuation and work within your emergency control organisation. The course focuses on practical responsibilities, communication and coordinated action during incidents. We can discuss training for a single site or teams across multiple locations.', 'Nominated fire wardens, facilities teams, building occupants with emergency responsibilities and workplace safety coordinators.', 'On-site group delivery by arrangement, subject to course and site requirements.'),
 ('chieffirewarden', 'Chief Fire Warden Training', 'Build the confidence to lead your workplace emergency control organisation when it matters.', 'Develop the leadership and coordination skills required of a chief warden during an emergency. Topics include managing an emergency response, directing wardens, communicating with emergency services and coordinating evacuation activity. Prerequisites and the issuing timeframe for any statement of attainment should be confirmed before booking.', 'Chief wardens, deputy chief wardens, emergency coordinators and experienced staff appointed to lead workplace emergency responses.', 'Group training at your workplace can be discussed; prerequisites and delivery requirements are confirmed before booking.'),
 ('lowvoltagerescue', 'Low Voltage Rescue & CPR Training', 'Specialist rescue preparation for electrical workers who may face a live low-voltage panel emergency.', 'Support your electrical safety procedures with practical training in preparing for a rescue, identifying isolation points, using rescue equipment and responding to a casualty. The nationally listed UETDRMP018 unit specifies HLTAID009 CPR as a prerequisite; we will confirm the appropriate training pathway and assessment arrangements for your team.', 'Electricians, electrical maintenance workers, switchboard personnel and safety observers working around low-voltage equipment.', 'Ask us about delivery for electrical teams and any equipment, prerequisite or site-specific requirements.')
)
UPDATE public.workplace_course_content AS w
SET workplace_title = copy.title,
    workplace_summary = copy.summary,
    workplace_description = copy.description,
    ideal_for = copy.ideal_for,
    delivery_options = copy.delivery,
    updated_at = NOW()
FROM public.courses AS c
JOIN copy ON copy.slug = c.slug
WHERE w.course_id = c.id;

-- Verify rows after updating:
SELECT c.slug, w.workplace_title, w.published, c.image_url
FROM public.workplace_course_content w
JOIN public.courses c ON c.id = w.course_id
ORDER BY COALESCE(w.display_order, c.display_order, 99);
